        r.count = r.count + 1
        local i = upvalues[4][1][r.count]
        i.start:init(b.x + R * v, b.y + L * v, b.z + w * v)
        i.finish:init(E.x, E.y, E.z)
        local z = V.tracer_color
        i.r, i.g, i.b, i.a = z.r, z.g, z.b, z.a
        i.width = V.tracer_width
        i.duration = V.tracer_lifetime * 0.1
        i.expires = globals.realtime + i.duration
        i.next_update = 0
    end
    if set_environment then
        set_environment(P, environment)
    end
    return P
end

